import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

function CreateJob() {
    const [formData, setFormData] = useState({
        title: '',
        description: '',
        requiredSkills: ''
    });
    const [error, setError] = useState('');
    const navigate = useNavigate();

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const skillsArray = formData.requiredSkills.split(',').map(s => s.trim()).filter(Boolean);
            await axios.post('http://localhost:5001/api/jobs', {
                title: formData.title,
                description: formData.description,
                requiredSkills: skillsArray
            }, { withCredentials: true });
            navigate('/jobs');
        } catch (err) {
            setError(err.response?.data?.error || 'Failed to create job');
        }
    };

    return (
        <div className="page mt-0 pb-20">
            <section className="bg-slate-50 pt-16 pb-12 border-b border-border-light mb-12">
                <div className="container">
                    <h1 className="text-2xl mb-2">Establish <span className="text-accent">New Requisition</span></h1>
                    <p className="muted">Configure the semantic parameters for your target candidate profile.</p>
                </div>
            </section>

            <div className="container">
                <div className="max-w-2xl mx-auto">
                    <div className="card" style={{ padding: '48px' }}>
                        <h3 className="text-xl mb-8">Requisition Intelligence</h3>

                        {error && <div className="alert alert-danger">{error}</div>}

                        <form onSubmit={handleSubmit} className="space-y-8">
                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black tracking-widest muted">Target Role Title</label>
                                <input
                                    type="text"
                                    className="form-input"
                                    name="title"
                                    value={formData.title}
                                    onChange={handleChange}
                                    placeholder="e.g. Senior Machine Learning Engineer"
                                    required
                                />
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black tracking-widest muted">Strategic Role Objectives</label>
                                <textarea
                                    className="form-textarea"
                                    name="description"
                                    value={formData.description}
                                    onChange={handleChange}
                                    rows="6"
                                    style={{ minHeight: '160px' }}
                                    placeholder="Describe the core business impact and technical expectations..."
                                ></textarea>
                            </div>

                            <div className="space-y-2">
                                <label className="text-[10px] uppercase font-black tracking-widest muted">Primary Competencies (CSV)</label>
                                <input
                                    type="text"
                                    className="form-input"
                                    name="requiredSkills"
                                    value={formData.requiredSkills}
                                    onChange={handleChange}
                                    placeholder="Python, TensorFlow, ETL, AWS, Kubernetes"
                                    required
                                />
                                <p className="muted text-[10px] mt-2 font-bold italic opacity-60">
                                    Semantic engine will prioritize these keywords during ingestion.
                                </p>
                            </div>

                            <div className="pt-8 border-t border-border-light">
                                <button type="submit" className="btn btn-primary w-full py-4 text-base">Deploy Requisition</button>
                            </div>
                        </form>
                    </div>
                </div>
            </div>
        </div>
    );
}

export default CreateJob;
